const KONTEXTE = ["privat", "arbeitgeber_visolva"];
const alle = $input.all();
if (alle.length !== 1) {
  throw new Error("evidence_verify_invalid_input: genau ein Aufruf je Ausfuehrung erwartet, erhalten " + alle.length);
}
const e = alle[0].json;
if (KONTEXTE.indexOf(e.context_id) === -1) {
  throw new Error("evidence_verify_invalid_input: context_id nicht im Register");
}
if (!e.action_id) {
  throw new Error("evidence_verify_invalid_input: action_id fehlt");
}
if (!/^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$/.test(String(e.contract_tool_id || ""))) {
  throw new Error("evidence_verify_invalid_input: contract_tool_id fehlt oder ist ungueltig");
}
if (!/^[0-9]+\.[0-9]+\.[0-9]+$/.test(String(e.contract_version || ""))) {
  throw new Error("evidence_verify_invalid_input: contract_version fehlt oder ist ungueltig");
}
if (!/^[a-z_]+$/.test(String(e.verification_method || ""))) {
  throw new Error("evidence_verify_invalid_input: verification_method fehlt oder ist ungueltig");
}
return [{ json: {
  context_id: e.context_id,
  action_id: e.action_id,
  contract_tool_id: e.contract_tool_id,
  contract_version: e.contract_version,
  verification_method: e.verification_method,
  observed: e.observed || {},
  expected: e.expected || {},
  trace_id: e.trace_id || null
} }];

// Entscheidung D3: Die Nachweisstrategie kommt ausschliesslich aus jarvis_ops.tool_registry.
// Angaben des Aufrufers zur Readback-Faehigkeit werden nicht beruecksichtigt.
const e = $('Eingabe pruefen').first().json;
const r = $input.first().json;
const beobachtet = e.observed || {};
const erwartet = e.expected || {};
let code = "";
let grund = "";
let bestanden = false;
if (r.found !== true) {
  code = "contract_unknown"; grund = "Werkzeugvertrag " + e.contract_tool_id + "@" + e.contract_version + " ist nicht im Register";
} else if (r.readback_supported === true && e.verification_method !== "readback") {
  code = "readback_required"; grund = "Readback ist laut Register moeglich und damit verpflichtend (D3)";
} else if ((r.accepted_methods || []).indexOf(e.verification_method) === -1) {
  code = "method_not_accepted"; grund = "Methode " + e.verification_method + " ist im Vertrag nicht zugelassen";
} else {
  const schluessel = Object.keys(erwartet);
  let abweichung = "";
  for (const k of schluessel) {
    if (JSON.stringify(beobachtet[k]) !== JSON.stringify(erwartet[k])) { abweichung = k; break; }
  }
  if (schluessel.length === 0) {
    code = "expected_empty"; grund = "Ohne erwarteten Zielzustand ist kein Abgleich moeglich";
  } else if (abweichung) {
    code = "mismatch"; grund = "Feld " + abweichung + " weicht vom erwarteten Zustand ab";
  } else {
    code = "verified"; bestanden = true;
  }
}
const ergebnis = bestanden ? "verified" : "failed";
return [{ json: {
  verification_passed: bestanden,
  verification_result: ergebnis,
  gate_code: code,
  reason: grund,
  verification: {
    method: e.verification_method,
    result: ergebnis,
    contract_ref: {
      tool_id: e.contract_tool_id,
      version: e.contract_version,
      readback_supported: r.found === true ? r.readback_supported : null
    },
    limitation: (r.found === true && r.readback_supported === false) ? r.evidence_limitation : null
  },
  action_id: e.action_id,
  context_id: e.context_id,
  observed_at: new Date().toISOString(),
  trace_id: e.trace_id
} }];
